mapper.select:
SELECT id AS batch_employee_id, health_examination_participant_id AS employee_id, participant_code_snapshot AS employee_code, department_snapshot AS department_name, job_title_snapshot, occupation_snapshot AS occupation, full_name_snapshot, date_of_birth_snapshot, sex_snapshot, identification_number_snapshot, identification_number_issue_date_snapshot, identification_number_issue_place_snapshot, ethnicity_snapshot, subject_type_snapshot, payer_source_snapshot, blood_group_snapshot, phone_snapshot, province_snapshot, ward_snapshot, address_detail_snapshot, administrative_occupation_snapshot, workplace_or_school_snapshot, health_examination_reason_snapshot, status, created_at FROM public.health_examination_batch_participants WHERE health_examination_batch_id = #{batchId}
ORDER BY
health_examination_participant_id participant_code_snapshot full_name_snapshot department_snapshot job_title_snapshot occupation_snapshot status created_at id
DESC ASC
, id ASC LIMIT #{limit} OFFSET #{offset}
